1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Item {
6	  type: string;
7	  material?: string;
8	  enchantment?: number;
9	  cursed?: boolean;
10	}
11	
12	export interface Damage {
13	  itemType: string;
14	  amount: number;
15	}
16	
17	export interface Incident {
18	  cause: string;
19	  damages: Damage[];
20	}
21	
22	export interface QuoteStep {
23	  op: "quote";
24	  items: Item[];
25	}
26	
27	export interface ClaimStep {
28	  op: "claim";
29	  policy: number;
30	  incident: Incident;
31	}
32	
33	export type Step = QuoteStep | ClaimStep;
34	
35	export interface Scenario {
36	  customer: Customer;
37	  steps: Step[];
38	}
39	
40	export interface QuoteResult {
41	  premium: number;
42	}
43	
44	export interface ClaimResult {
45	  payout: number;
46	  remainingCap: number;
47	}
48	
49	export type StepResult = QuoteResult | ClaimResult;
50	
51	export interface ScenarioResult {
52	  results: StepResult[];
53	}
54	
55	const PROCESSING_FEE = 5;
56	
57	// One row per item type the office recognises. Base premium (what it costs to
58	// insure) and insurance value (what it is insured FOR) are independent numbers,
59	// but they are known for exactly the same set of types — so they belong in one
60	// table. Keeping them apart would leave two key sets that must agree with
61	// nothing enforcing it.
62	interface ItemSpec {
63	  basePremium: number;
64	  insuranceValue: number;
65	}
66	
67	const ITEM_SPECS = {
68	  sword: { basePremium: 100, insuranceValue: 1000 },
69	  amulet: { basePremium: 60, insuranceValue: 600 },
70	  staff: { basePremium: 80, insuranceValue: 800 },
71	  potion: { basePremium: 40, insuranceValue: 400 },
72	  rune: { basePremium: 25, insuranceValue: 250 },
73	  moonstone: { basePremium: 25, insuranceValue: 250 },
74	} as const satisfies Record<string, ItemSpec>;
75	
76	type KnownItemType = keyof typeof ITEM_SPECS;
77	
78	const isKnownItemType = (type: string): type is KnownItemType =>
79	  type in ITEM_SPECS;
80	
81	// The office insures only what its price list names. An unknown type has no
82	// premium and no insurance value, so there is nothing to quote — the whole
83	// scenario is rejected rather than priced at zero.
84	const specForItem = (item: Item): ItemSpec => {
85	  if (!isKnownItemType(item.type)) {
86	    throw new Error(`The MHPCO does not insure items of type ${item.type}`);
87	  }
88	  return ITEM_SPECS[item.type];
89	};
90	
91	const basePremiumForItem = (item: Item): number => specForItem(item).basePremium;
92	
93	const BLOCK_SIZE = 3;
94	
95	const BLOCK_BASE_PREMIUM = 60;
96	
97	const sum = (amounts: number[]): number =>
98	  amounts.reduce((total, amount) => total + amount, 0);
99	
100	// "Alike" means the same exact type, not merely the same family: two runes and
101	// a moonstone are three components but not three alike ones, so grouping them
102	// by type keeps them apart and denies them the block price.
103	const groupByType = (items: Item[]): Item[][] => {
104	  const groups = new Map<string, Item[]>();
105	  for (const item of items) {
106	    groups.set(item.type, [...(groups.get(item.type) ?? []), item]);
107	  }
108	  return [...groups.values()];
109	};
110	
111	// A block is not carved out of a larger group: the block price applies only
112	// when the group consists of exactly three alike components (7 runes cost
113	// 7 × 25, not 60 + 60 + 25). Alikeness is guaranteed by the caller, which only
114	// ever passes a single group from groupByType.
115	const basePremiumForGroup = (group: Item[]): number =>
116	  group.length === BLOCK_SIZE
117	    ? BLOCK_BASE_PREMIUM
118	    : sum(group.map(basePremiumForItem));
119	
120	const basePremiumForItems = (items: Item[]): number =>
121	  sum(groupByType(items).map(basePremiumForGroup));
122	
123	const CURSE_SURCHARGE = 0.5;
124	
125	// Every modifier is an additive percentage of its OWN base — modifiers never
126	// compound with each other. Item-scoped modifiers take the affected item's base
127	// premium as their base; policy-scoped modifiers take the policy base premium
128	// (the sum of all item base premiums). So the total is always
129	// base + Σ (rate × that modifier's base), never a product of (1 + rate) factors.
130	const modifierAmount = (rate: number, base: number): number => rate * base;
131	
132	const ENCHANTMENT_SURCHARGE = 0.3;
133	
134	const ENCHANTMENT_SURCHARGE_LEVEL = 5;
135	
136	const isCursed = (item: Item): boolean => item.cursed === true;
137	
138	const attractsEnchantmentSurcharge = (item: Item): boolean =>
139	  (item.enchantment ?? 0) >= ENCHANTMENT_SURCHARGE_LEVEL;
140	
141	interface ItemModifier {
142	  rate: number;
143	  appliesTo: (item: Item) => boolean;
144	}
145	
146	// Each item-scoped modifier is a row: a rate and the condition under which it
147	// applies. The predicate names the modifier, so a row needs no separate label.
148	// Adding a modifier means adding a row, not a new branch.
149	const ITEM_MODIFIERS: ItemModifier[] = [
150	  { rate: CURSE_SURCHARGE, appliesTo: isCursed },
151	  { rate: ENCHANTMENT_SURCHARGE, appliesTo: attractsEnchantmentSurcharge },
152	];
153	
154	const itemModifierRates = (item: Item): number[] =>
155	  ITEM_MODIFIERS.filter((modifier) => modifier.appliesTo(item)).map(
156	    (modifier) => modifier.rate,
157	  );
158	
159	const LOYALTY_DISCOUNT = 0.2;
160	
161	const LOYALTY_THRESHOLD_YEARS = 2;
162	
163	const isLongStanding = (customer: Customer): boolean =>
164	  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS;
165	
166	// Discounts are surcharges with the sign flipped: expressing one as a negative
167	// rate lets it flow through the same additive sum as every surcharge, with no
168	// separate subtraction step. Discount constants stay positive magnitudes and
169	// are negated here, at the point of use, so the direction is visible in the
170	// rate list rather than buried in a constant's sign.
171	const asDiscount = (rate: number): number => -rate;
172	
173	const INITIAL_ASSESSMENT_SURCHARGE = 0.1;
174	
175	const FOLLOW_UP_CONTRACT_DISCOUNT = 0.15;
176	
177	// Policy-scoped modifiers apply to the policy base premium. Unlike item
178	// modifiers they select on the customer and on the quote's position in the
179	// scenario rather than on an item.
180	//
181	// The initial-assessment surcharge applies to every quote: each item is treated
182	// as a first insurance regardless of customer history. The follow-up discount
183	// is what distinguishes a customer's later contracts.
184	const policyModifierRates = (
185	  customer: Customer,
186	  isFollowUpContract: boolean,
187	): number[] => [
188	  INITIAL_ASSESSMENT_SURCHARGE,
189	  ...(isLongStanding(customer) ? [asDiscount(LOYALTY_DISCOUNT)] : []),
190	  ...(isFollowUpContract ? [asDiscount(FOLLOW_UP_CONTRACT_DISCOUNT)] : []),
191	];
192	
193	const itemModifiersTotal = (items: Item[]): number =>
194	  sum(
195	    items.flatMap((item) =>
196	      itemModifierRates(item).map((rate) =>
197	        modifierAmount(rate, basePremiumForItem(item)),
198	      ),
199	    ),
200	  );
201	
202	const policyModifiersTotal = (
203	  policyBasePremium: number,
204	  customer: Customer,
205	  isFollowUpContract: boolean,
206	): number =>
207	  sum(
208	    policyModifierRates(customer, isFollowUpContract).map((rate) =>
209	      modifierAmount(rate, policyBasePremium),
210	    ),
211	  );
212	
213	// All amounts are rounded to whole G in the MHPCO's favour. Which way that
214	// points depends on which way the money flows: a premium comes in, so it rounds
215	// up; a payout goes out, so it rounds down.
216	//
217	// Two functions rather than one taking a direction, so that knowing which way
218	// favour points for a given kind of money stays here. A direction parameter
219	// would push that back onto every caller — the one thing these exist to answer.
220	const roundPremiumInMHPCOsFavour = (amount: number): number =>
221	  Math.ceil(amount);
222	
223	const roundPayoutInMHPCOsFavour = (amount: number): number =>
224	  Math.floor(amount);
225	
226	const quotePremium = (
227	  items: Item[],
228	  customer: Customer,
229	  isFollowUpContract: boolean,
230	): number => {
231	  const policyBasePremium = basePremiumForItems(items);
232	  return roundPremiumInMHPCOsFavour(
233	    policyBasePremium +
234	      itemModifiersTotal(items) +
235	      policyModifiersTotal(policyBasePremium, customer, isFollowUpContract) +
236	      PROCESSING_FEE,
237	  );
238	};
239	
240	const insuranceValueForItem = (item: Item): number =>
241	  specForItem(item).insuranceValue;
242	
243	// Deliberately NOT the shape of basePremiumForItems. Both aggregate a per-item
244	// figure from ITEM_SPECS, but the premium side groups by type first so a block
245	// of three alike components can be priced as one; this side never groups. Three
246	// runes cost 60 to insure and are insured for 3 × 250 = 750. The block is a
247	// discount on the price of cover, not a reduction of the cover bought.
248	//
249	// So the near-symmetry is a false friend: factoring the two into one traversal
250	// would read as tidier and would silently make blocks shrink the insurance sum.
251	// The repetition of `sum(items.map(...))` is the price of keeping them free to
252	// diverge, and is paid on purpose.
253	const insuranceSum = (items: Item[]): number =>
254	  sum(items.map(insuranceValueForItem));
255	
256	const CAP_MULTIPLE = 2;
257	
258	// The cap is twice the insurance sum — the value the items are insured FOR, so
259	// it is computed from the items alone and never from the premium. Curses,
260	// enchantments and loyalty change what a policy costs without changing what it
261	// covers (as do blocks — see insuranceSum). Naming the relation keeps that
262	// separation visible at the one place a policy is created.
263	const capForItems = (items: Item[]): number =>
264	  CAP_MULTIPLE * insuranceSum(items);
265	
266	const DEDUCTIBLE = 100;
267	
268	interface Policy {
269	  items: Item[];
270	  remainingCap: number;
271	}
272	
273	// Steps are not independent: a quote's premium depends on how many quotes came
274	// before it, and a claim draws down the cap of a policy an earlier quote
275	// created. So a step is a function from state to (result, next state), and the
276	// scenario is a fold over that — not a map, which would promise an independence
277	// the steps do not have.
278	//
279	// Policies are keyed by the index of the quote step that created them: a claim
280	// step names its policy by that zero-based index.
281	interface ScenarioState {
282	  quotesSoFar: number;
283	  policies: Map<number, Policy>;
284	}
285	
286	const INITIAL_STATE: ScenarioState = {
287	  quotesSoFar: 0,
288	  policies: new Map(),
289	};
290	
291	interface StepOutcome {
292	  result: StepResult;
293	  state: ScenarioState;
294	}
295	
296	// Both operations end by filing a policy under its quote's index — a claim
297	// re-files the same policy with a drawn-down cap. Naming that once keeps the
298	// Map out of the operations, so neither has to know how policies are stored.
299	const withPolicy = (
300	  state: ScenarioState,
301	  policyIndex: number,
302	  policy: Policy,
303	): ScenarioState => ({
304	  ...state,
305	  policies: new Map(state.policies).set(policyIndex, policy),
306	});
307	
308	const runQuote = (
309	  step: QuoteStep,
310	  customer: Customer,
311	  state: ScenarioState,
312	  stepIndex: number,
313	): StepOutcome => ({
314	  result: {
315	    premium: quotePremium(step.items, customer, state.quotesSoFar > 0),
316	  },
317	  state: withPolicy(
318	    { ...state, quotesSoFar: state.quotesSoFar + 1 },
319	    stepIndex,
320	    {
321	      items: step.items,
322	      remainingCap: capForItems(step.items),
323	    },
324	  ),
325	});
326	
327	const REDUCED_REIMBURSEMENT_ENCHANTMENT_LEVEL = 8;
328	
329	const REDUCED_REIMBURSEMENT_RATE = 0.5;
330	
331	const FULL_REIMBURSEMENT_RATE = 1;
332	
333	// Reads enchantment like the premium-side surcharge rule, but is a different
334	// rule with its own level: this one halves what a claim pays out, that one
335	// raises what a policy costs. Sharing a predicate would tie two levels that the
336	// spec lets move independently, so the shape is repeated deliberately.
337	const qualifiesForReducedReimbursement = (item: Item): boolean =>
338	  (item.enchantment ?? 0) >= REDUCED_REIMBURSEMENT_ENCHANTMENT_LEVEL;
339	
340	// The reimbursement rate is decided first, then one deductible comes off.
341	//
342	// The dragon-material clause is absent on purpose, not by oversight. It promises
343	// full reimbursement of the damage before the deductible — which is exactly what
344	// FULL_REIMBURSEMENT_RATE already gives every item that misses the reduced-rate
345	// clause. Where both clauses apply the spec awards it to the 50 % rule. Between
346	// them the two facts leave the clause with no input it can move: dragon material
347	// at enchantment 9 or 8 pays the same 400 as steel at those levels, and at
348	// enchantment 5 it pays the same 700 steel would. Writing it as its own branch
349	// would add a branch no test could ever tell from the default — a distinction
350	// the domain does not make.
351	const reimbursementRate = (item: Item): number =>
352	  qualifiesForReducedReimbursement(item)
353	    ? REDUCED_REIMBURSEMENT_RATE
354	    : FULL_REIMBURSEMENT_RATE;
355	
356	const payoutForDamage = (damage: Damage, item: Item): number =>
357	  damage.amount * reimbursementRate(item) - DEDUCTIBLE;
358	
359	// Returns AN insured item of the damaged type, not THE damaged one — a policy
360	// can cover two swords, so the type does not name a unique item. Two damage
361	// entries of the same type are both answered with the same first match.
362	//
363	// That is sound today because the answer is used solely to read payout
364	// attributes (the reimbursement rate), and the covered case — two damages
365	// against two swords — insures identical swords, which read the same either
366	// way. The deductible is charged per damage entry, not per matched item, so
367	// counting is unaffected too.
368	//
369	// One thing would break it, not yet under test: two swords with DIFFERENT
370	// attributes (say enchantment 3 and 9). Both damages would take the first
371	// sword's rate; the second should take its own. This lookup must then become a
372	// pairing that consumes what it matches. The honest name marks that spot.
373	//
374	// The `!` is a proof, not an assumption: rejectUnmatchedDamages runs first and
375	// throws unless every claimed type is covered at least as many times as it is
376	// named — so by the time this runs, a match exists for every damage entry. Both
377	// ways it could fail are covered by tests: claiming a type more often than it is
378	// insured, and claiming a type the policy does not cover at all.
379	const anInsuredItemOfDamagedType = (policy: Policy, damage: Damage): Item =>
380	  policy.items.find((item) => item.type === damage.itemType)!;
381	
382	// Counts how many times each value occurs. Deliberately typed on strings rather
383	// than on Item: the guard below tallies two different things (item types held
384	// and item types named by damages) and only their counts are ever compared, so
385	// the tally has no business knowing what the strings mean.
386	const tally = (values: string[]): Map<string, number> => {
387	  const counts = new Map<string, number>();
388	  for (const value of values) {
389	    counts.set(value, (counts.get(value) ?? 0) + 1);
390	  }
391	  return counts;
392	};
393	
394	// Every damage entry must claim an insured item of its own, so a type cannot be
395	// damaged more times than the policy covers it. One rule, two error cases the
396	// spec states separately: claiming a type more often than it is insured, and
397	// claiming a type the policy does not cover at all. The second is the first at
398	// zero — an uninsured type is covered 0 times against a claimed 1 — so both are
399	// caught by the same comparison rather than by a separate membership test.
400	//
401	// Checked before any payout is computed: the spec rejects the whole claim, not
402	// just the surplus entries.
403	const rejectUnmatchedDamages = (policy: Policy, incident: Incident): void => {
404	  const insured = tally(policy.items.map((item) => item.type));
405	  const claimed = tally(incident.damages.map((damage) => damage.itemType));
406	  for (const [type, claimedCount] of claimed) {
407	    const insuredCount = insured.get(type) ?? 0;
408	    if (claimedCount > insuredCount) {
409	      throw new Error(
410	        `Policy covers ${insuredCount} ${type}(s) but the claim names ${claimedCount}`,
411	      );
412	    }
413	  }
414	};
415	
416	// A damage is what an incident cost the owner, so it cannot be negative. Zero
417	// is left alone: the spec forbids only negative amounts, and a zero damage
418	// simply pays nothing once the deductible bites.
419	const isNegative = (damage: Damage): boolean => damage.amount < 0;
420	
421	const rejectNegativeDamages = (incident: Incident): void => {
422	  const negative = incident.damages.find(isNegative);
423	  if (negative) {
424	    throw new Error(
425	      `Damage to ${negative.itemType} is negative: ${negative.amount}`,
426	    );
427	  }
428	};
429	
430	// Both guards run before any payout is computed: the spec rejects the whole
431	// claim, not just the offending entries, so a valid entry alongside an invalid
432	// one must not be paid.
433	//
434	// They are two statements rather than a list of validations. Their signatures
435	// differ (only the first needs the policy), so a uniform list could hold them
436	// only by giving the second a parameter it ignores. And the order is not
437	// incidental: rejectUnmatchedDamages must come first because it is what makes
438	// the lookup in anInsuredItemOfDamagedType total — an obligation that reads as
439	// a sequenced line here but would vanish into array order in a list. The third
440	// validation the spec calls for (unknown item type) belongs to the quote path,
441	// so this pair is closed at two and has no growth to abstract over.
442	const payoutForIncident = (policy: Policy, incident: Incident): number => {
443	  rejectUnmatchedDamages(policy, incident);
444	  rejectNegativeDamages(incident);
445	  return sum(
446	    incident.damages.map((damage) =>
447	      payoutForDamage(damage, anInsuredItemOfDamagedType(policy, damage)),
448	    ),
449	  );
450	};
451	
452	// The damage decides what a claim is WORTH; the cap decides what there is left
453	// to pay it WITH. Once the cap is spent the office pays what remains, not what
454	// was asked — so the cap bounds the payout before it is charged against it.
455	//
456	// This is the guarantee that makes drawDownCap's subtraction safe: a payout that
457	// has passed through here can never exceed the balance, so the balance can never
458	// go negative. The two are a pair — bound, then spend — and neither is sound
459	// without the other.
460	const payoutWithinCap = (payout: number, remainingCap: number): number =>
461	  Math.min(payout, remainingCap);
462	
463	// A policy's cap is a balance, not a per-claim limit: each claim spends part of
464	// it and the rest carries forward to the next claim against the same policy.
465	// The balance stays non-negative because payoutWithinCap has already bounded
466	// what is spent — this subtraction does not defend itself, it relies on that.
467	//
468	// Naming the draw-down separates what the cap DOES from how a claim is assembled
469	// — the one line in runClaim that was arithmetic rather than plumbing.
470	const drawDownCap = (remainingCap: number, payout: number): number =>
471	  remainingCap - payout;
472	
473	const runClaim = (step: ClaimStep, state: ScenarioState): StepOutcome => {
474	  // A claim naming a policy that does not exist is a spec error case, but no
475	  // test drives it yet. The assertion stands in until one does — at which point
476	  // the missing case becomes the error branch rather than a crash.
477	  const policy = state.policies.get(step.policy)!;
478	  // Rounded before the clamp so the cap is only ever compared with, and reduced
479	  // by, whole G — a fractional payout would otherwise leave a fractional cap
480	  // behind for the next claim.
481	  const claimWorth = roundPayoutInMHPCOsFavour(
482	    payoutForIncident(policy, step.incident),
483	  );
484	  const payout = payoutWithinCap(claimWorth, policy.remainingCap);
485	  const remainingCap = drawDownCap(policy.remainingCap, payout);
486	  return {
487	    result: { payout, remainingCap },
488	    state: withPolicy(state, step.policy, { ...policy, remainingCap }),
489	  };
490	};
491	
492	// Dispatch decides once what a step is; each operation then owns both its
493	// result and how it advances the state, so no caller has to re-test step.op to
494	// know what the step did.
495	const runStep = (
496	  step: Step,
497	  customer: Customer,
498	  state: ScenarioState,
499	  stepIndex: number,
500	): StepOutcome =>
501	  step.op === "quote"
502	    ? runQuote(step, customer, state, stepIndex)
503	    : runClaim(step, state);
504	
505	// The fold carries both halves of the outcome: the results accumulated so far
506	// and the state the next step will see. Threading the state explicitly (rather
507	// than recovering it from the last result) keeps the dependency between steps
508	// visible in the type.
509	interface ScenarioRun {
510	  results: StepResult[];
511	  state: ScenarioState;
512	}
513	
514	const INITIAL_RUN: ScenarioRun = { results: [], state: INITIAL_STATE };
515	
516	const appendStep =
517	  (customer: Customer) =>
518	  (run: ScenarioRun, step: Step, stepIndex: number): ScenarioRun => {
519	    const outcome = runStep(step, customer, run.state, stepIndex);
520	    return {
521	      results: [...run.results, outcome.result],
522	      state: outcome.state,
523	    };
524	  };
525	
526	export const runScenario = ({ customer, steps }: Scenario): ScenarioResult => ({
527	  results: steps.reduce(appendStep(customer), INITIAL_RUN).results,
528	});
